                'loc_body'       => ['Torosların eteklerinden inen bir vadinin ucunda, sessiz bir kıyıda. Antik kalıntılar, yanmaya devam eden efsanevi alevler ve masmavi bir deniz.', 'At the end of a valley where the Taurus Mountains meet the sea. Ancient ruins, mythological flames, and the calm of the Mediterranean.', 'Am Ende eines Tals, wo die Taurusberge auf das Meer treffen. Antike Ruinen, mythologische Flammen und die Stille des Mittelmeers.'],
                'loc_cta'        => ['Keşfet →', 'Explore →', 'Entdecken →'],
            ],
            'voices' => [
                'label'   => ['Hakkımızda Yazılanlar', 'In Print', 'In der Presse'],
                'heading' => ['Kelimelerle.', 'In words.', 'In Worten.'],
                'items'   => [
                    json_encode([['text' => '"Bilen gelsin, bilmeyenlere anlatsın ve sadece meraklısını ağırlasın diye düşünülmüş gizli saklı bir dünya."', 'author' => '— Saffet Emre Tonguç<br><em>Butik Oteller: Türkiye\'den Seçtiklerim</em>'], ['text' => '"Gerçek bir sığınak. Her şeyden tamamen uzaklaşıp daha yavaş, daha düşünceli ve daha huzurlu bir yaşam biçimine geçme fırsatı."', 'author' => '— Elixir<br><em>Turkish Collection</em>'], ['text' => '"Bu bahçede yürürken, zamanın gerçekten durduğunu hissettim. Her köşede huzur, her detayda özen."', 'author' => '— Bir misafir, 2023']]),
                    json_encode([['text' => '"Come if you know; tell those who don\'t, and welcome only the curious — a hidden world designed for those who seek it."', 'author' => '— Saffet Emre Tonguç<br><em>Boutique Hotels: My Picks from Turkey</em>'], ['text' => '"A true sanctuary. The chance to completely disconnect from everything and step into a slower, more thoughtful, more peaceful way of living."', 'author' => '— Elixir<br><em>Turkish Collection</em>'], ['text' => '"Walking through this garden, I felt time truly stand still. Peace in every corner, care in every detail."', 'author' => '— A guest, 2023']]),
                    json_encode([['text' => '"Komm, wenn du es weißt; erzähl es denen, die es nicht wissen, und empfange nur die Neugierigen — eine verborgene Welt für jene, die sie suchen."', 'author' => '— Saffet Emre Tonguç<br><em>Boutique Hotels: Meine Auswahl aus der Türkei</em>'], ['text' => '"Ein echtes Refugium. Die Chance, sich von allem vollständig zu lösen und in eine langsamere, nachdenklichere und friedlichere Lebensweise einzutauchen."', 'author' => '— Elixir<br><em>Turkish Collection</em>'], ['text' => '"Beim Spaziergang durch diesen Garten spürte ich, wie die Zeit wirklich still stand. Frieden in jeder Ecke, Sorgfalt in jedem Detail."', 'author' => '— Ein Gast, 2023']]),
                ],
            ],
